post_content:
{#
  =============================================================================
  HERO: Nächstes Spiel (Titelbereich)
  - team_slug wie in den Listen-Views (post.match_team_key auf Team-Seite)
  - Logos: include('partial-club-team-logo') mit Eager-Loading / fetchpriority
  - Sportplatz: nur wenn rwmb_meta sports_ground_address am Heim-Club nicht leer
  =============================================================================
#}
{% set group = attribute(site, 'club-einstellungen') %}
{% set team_slug = (post is defined) ? (attribute(post, 'match_team_key')|default('erste')) : 'erste' %}
{% set all_matches = attribute(group, 'club_matchdays') %}

{% set matches = all_matches|length >= 1
  ? all_matches
    |filter(v => (attribute(v, 'team').value|default(attribute(v, 'team'))) == team_slug)
    |filter(v => attribute(v, 'match_datetime').timestamp > mb.microtime(true))
    |sort((a, b) => attribute(a, 'match_datetime').timestamp <=> attribute(b, 'match_datetime').timestamp)
  : []
%}

{% if matches|length > 0 %}
  <div class="match-hero-wrap">
  {% set match = matches|first %}
  {% set sports_ground = mb.rwmb_meta('sports_ground_address', null, match.home_team.ID) %}
  {% set dt_iso = match.match_datetime.timestamp|date('c') %}
  <section class="match-hero" aria-labelledby="match-hero-title">
    <h2 id="match-hero-title" class="match-hero__heading">Nächstes Spiel</h2>
    <div class="match-lineup match-hero__lineup" role="group" aria-label="{{ match.home_team.title }} gegen {{ match.away_team.title }}">
      <div class="match-lineup__side match-lineup__side--home">
        <p class="match-lineup__name">{{ match.home_team.title }}</p>
        {% set team_post = match.home_team %}
        {% set logo_max_width = 100 %}
        {% set logo_max_height = 100 %}
        {% set logo_loading = 'eager' %}
        {% set logo_fetchpriority = 'high' %}
        {{ include('partial-club-team-logo') }}
      </div>
      <div class="match-lineup__center" aria-hidden="true">
        <p class="match-lineup__vs">vs</p>
      </div>
      <div class="match-lineup__side match-lineup__side--away">
        <p class="match-lineup__name">{{ match.away_team.title }}</p>
        {% set team_post = match.away_team %}
        {% set logo_max_width = 100 %}
        {% set logo_max_height = 100 %}
        {% set logo_loading = 'eager' %}
        {% set logo_fetchpriority = 'high' %}
        {{ include('partial-club-team-logo') }}
      </div>
    </div>
    <div class="match-hero__details">
      <p class="match-hero__row"><span class="match-hero__label">Liga</span> {{ match.league }}</p>
      <p class="match-hero__row">
        <span class="match-hero__label">Anstoß</span>
        <time class="match-hero__time" datetime="{{ dt_iso }}">{{ match.match_datetime.timestamp|date('d.m.Y') }} um {{ match.match_datetime.timestamp|date('H:i') }} Uhr</time>
      </p>
      {% if sports_ground is not empty and sports_ground|trim|length > 0 %}
        <p class="match-hero__row"><span class="match-hero__label">Ort</span> {{ sports_ground }}</p>
      {% endif %}
    </div>
  </section>
  </div>
{% else %}
  <div class="match-hero-wrap">
  <div class="match-hero match-hero--empty" role="status" aria-live="polite">
    <p class="match-hero__empty">Aktuell sind keine Spiele geplant.</p>
  </div>
  </div>
{% endif %}
